-- =====================================================================
-- V2__seed_fake_data.sql  (SQL Server)
-- Fake data cho TOAN BO bang cua V1__init_schema.sql.
-- Thay the cho V2__seed_fake_catalog.sql + V3__seed_fake_stories.sql cu
-- (chay ngay sau V1, tren DB chua co du lieu catalog).
--
-- Nguyen tac:
--  * Moi ngay thang tinh theo @today (ngay chay script) => du lieu luon
--    nhat quan: cuon "OVERDUE" luon that su qua han, cuon sap den han
--    luon sap den han... bat ke chay vao ngay nao.
--  * Trang thai tra sach nam o TUNG CUON (borrow_details.status), vi mot
--    phieu muon co the duoc tra tung phan. borrow_records khong con status.
--  * CHAY THU CONG trong SQL Server (KHONG qua Flyway), SAU KHI Flyway da chay V1.
--  * roles (ADMIN/LIBRARIAN/MEMBER/READER) / permissions / role_permissions /
--    settings da co tu V1 -> KHONG insert lai, chi doc settings de tinh tien phat / phi the.
--  * Tien phat, so luong ton, trang thai cuon, thong bao deu duoc TINH
--    tu du lieu goc (khong go tay) + co khoi kiem tra o cuoi file.
--  * Mat khau tat ca tai khoan: Library@123 (cung hash voi V1).
--  * users.avatar va books.cover luu base64 dang DATA URI (data:image/...;base64,...)
--    giong quy uoc cua V1 (xem cac bien @avatar1/2, @cover1/2).
--
-- CHANGELOG so voi ban truoc (da doi chieu voi V1__init_schema.sql):
--  1. avatar / cover: them tien to data URI (truoc day la base64 tho -> khong hien thi duoc)
--  2. members.created_at: dong bo voi thoi diem nop phi dang ky (truoc day = ngay chay script)
--  3. fines.reason: sua DAMAGED_HEAVY_REPAIRABLE / DAMAGED_HEAVY_IRREPARABLE bi gan nham
--     (reason khong khop he so + ghi chu); bo sung 1 mau DAMAGED_HEAVY_IRREPARABLE that (BR18)
--     kem tru kho; fines.attachment co o moi khoan phat LOST / DAMAGED_*
--  4. REISSUE: lay phi tu settings.CARD_MAKER_FEE (truoc day go tay 20.000, bo qua setting)
--  5. Nhac han tra: theo settings.DUE_REMINDER_DAYS (truoc day hard-code 'hom nay + ngay mai')
--  6. notifications.created_at khong bao gio nam trong tuong lai (chay script truoc 08:00)
--  7. TV000004: nop phat truoc ngay muon BR22 (khong muon khi no phat > MAX_FINE_BEFORE_BLOCK)
--  8. Them cac khoi kiem tra 7.14 - 7.17
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @today DATE = CAST(SYSDATETIME() AS DATE);
DECLARE @pwd   VARCHAR(255) = '$2a$10$oBtQmWU9wIIEqhe8n5FS1.NcukW5XEGg.T/51Sgmap.RpTZozW3va';
-- anh PNG 1x1 dung lam file dinh kem mau cho bien ban phat
DECLARE @img   VARCHAR(MAX) = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';

-- Anh mau (base64 DATA URI) cho avatar (users) va cover (books): 3 anh JPEG + 1 anh WEBP
DECLARE @avatar1 VARCHAR(MAX) = 'data:image/jpeg;base64,';
DECLARE @avatar2 VARCHAR(MAX) = 'data:image/jpeg;base64,';
DECLARE @cover1  VARCHAR(MAX) = 'data:image/jpeg;base64,';
DECLARE @cover2  VARCHAR(MAX) = 'data:image/webp;base64,';

-- Dieu kien tien quyet: V1 (ban moi, READER co 10 quyen) phai da chay (du 4 role)
DECLARE @role_cnt INT = (SELECT COUNT(*) FROM roles
                         WHERE name IN ('ADMIN','LIBRARIAN','MEMBER','READER') AND is_deleted = 0);
IF @role_cnt <> 4
    THROW 50000, N'Thieu role ADMIN/LIBRARIAN/MEMBER/READER. Hay chay V1 (Flyway) truoc.', 1;

-- So ngay nhac truoc han (settings.DUE_REMINDER_DAYS) va moc 08:00 hom nay (khong cho phep nam trong tuong lai)
DECLARE @remind_days INT = (SELECT CAST(setting_value AS INT) FROM settings
                            WHERE setting_key = 'DUE_REMINDER_DAYS' AND is_deleted = 0);
DECLARE @morning DATETIME2 = DATEADD(HOUR, 8, CAST(@today AS DATETIME2));
IF @morning > SYSDATETIME() SET @morning = SYSDATETIME();

BEGIN TRANSACTION;

-- =====================================================================
-- 1. USERS / MEMBERS
-- =====================================================================

-- Lam "gia" tai khoan demo cua V1 de co lich su (tao tu ngay cu thay vi hom nay)
-- Quy tac nghiep vu: tai khoan DOC GIA chi duoc tao khi dang ky the thanh vien voi thu thu
-- => moi user role MEMBER deu co dung 1 ban ghi members + 1 khoan phi REGISTER, va
--    users.created_at = thoi diem nop phi dang ky (dong bo o muc "member_payments" ben duoi).
-- Tai khoan READER (doc gia chua co the) khong co ban ghi members. Admin / thu thu la nhan su,
-- khong phai thanh vien nen cung khong co ban ghi members.
UPDATE users SET created_at = DATEADD(DAY, -600, SYSDATETIME())
WHERE username IN ('admin', 'librarian') AND is_deleted = 0;

-- Nguon du lieu duy nhat cho thanh vien (dung cho users, members, member_payments)
CREATE TABLE #mem_seed (
    username           VARCHAR(50),
    full_name          NVARCHAR(100),
    no_accent          VARCHAR(100),
    email              VARCHAR(100),
    member_code        VARCHAR(20),
    phone              VARCHAR(15),
    identity_number    VARCHAR(12),
    address            NVARCHAR(255),
    reg_days_ago       INT,           -- dang ky the cach day bao nhieu ngay
    renew_days_before  INT NULL,      -- NULL = chua gia han; so = gia han truoc ngay het han N ngay (them 1 nam)
    registrar          VARCHAR(50),   -- thu thu thu phi dang ky
    is_active          BIT,
    failed_attempts    INT,
    card_status        VARCHAR(10)    -- ISSUED = da cap the, PENDING = doi cap the
);

