 ('tranthibinh',   N'Trần Thị Bình',   'tran thi binh',   'tranthibinh@example.com',     'TV000003', '0912000003', '001201000003', N'45 Cầu Giấy, Cầu Giấy, Hà Nội',         420, 7,    'librarian', 1, 0, 'ISSUED'),
 ('lehoangcuong',  N'Lê Hoàng Cường',  'le hoang cuong',  'lehoangcuong@example.com',    'TV000004', '0912000004', '001201000004', N'8 Nguyễn Trãi, Thanh Xuân, Hà Nội',     150, NULL, 'thuthu02',  1, 0, 'ISSUED'),
 ('phamminhduc',   N'Phạm Minh Đức',   'pham minh duc',   'phamminhduc@example.com',     'TV000005', '0912000005', '001201000005', N'20 Láng Hạ, Đống Đa, Hà Nội',           300, NULL, 'librarian', 1, 0, 'ISSUED'),
 ('hoangthuha',    N'Hoàng Thu Hà',    'hoang thu ha',    'hoangthuha@example.com',      'TV000006', '0912000006', '001201000006', N'3 Kim Mã, Ba Đình, Hà Nội',             60,  NULL, 'thuthu02',  1, 0, 'ISSUED'),
 ('vuquanghuy',    N'Vũ Quang Huy',    'vu quang huy',    'vuquanghuy@example.com',      'TV000007', '0912000007', '001201000007', N'77 Tây Sơn, Đống Đa, Hà Nội',           45,  NULL, 'librarian', 1, 0, 'ISSUED'),
 ('dangkhanhlinh', N'Đặng Khánh Linh', 'dang khanh linh', 'dangkhanhlinh@example.com',   'TV000008', '0912000008', '001201000008', N'15 Giảng Võ, Ba Đình, Hà Nội',          500, 5,    'librarian', 1, 0, 'ISSUED'),
 ('buiducmanh',    N'Bùi Đức Mạnh',    'bui duc manh',    'buiducmanh@example.com',      'TV000009', '0912000009', '001201000009', N'102 Minh Khai, Hai Bà Trưng, Hà Nội',   30,  NULL, 'thuthu02',  1, 0, 'ISSUED'),
 ('ngothanhnam',   N'Ngô Thanh Nam',   'ngo thanh nam',   'ngothanhnam@example.com',     'TV000010', '0912000010', '001201000010', N'9 Hoàng Quốc Việt, Cầu Giấy, Hà Nội',   250, NULL, 'librarian', 1, 0, 'ISSUED'),
 ('dothiphuong',   N'Đỗ Thị Phương',   'do thi phuong',   'dothiphuong@example.com',     'TV000011', '0912000011', '001201000011', N'66 Trần Duy Hưng, Cầu Giấy, Hà Nội',    120, NULL, 'thuthu02',  1, 0, 'ISSUED'),
 ('lyvanquang',    N'Lý Văn Quang',    'ly van quang',    'lyvanquang@example.com',      'TV000012', '0912000012', '001201000012', N'31 Đê La Thành, Đống Đa, Hà Nội',       400, NULL, 'librarian', 1, 0, 'ISSUED'),  -- the da het han, khong gia han
 ('maithisen',     N'Mai Thị Sen',     'mai thi sen',     'maithisen@example.com',       'TV000013', '0912000013', '001201000013', N'5 Lê Duẩn, Hoàn Kiếm, Hà Nội',          180, NULL, 'thuthu02',  0, 5, 'ISSUED'),     -- tai khoan bi khoa
 ('trinhbaochau', N'Trịnh Bảo Châu', 'trinh bao chau', 'trinhbaochau@example.com',    'TV000014', '0912000014', '001201000014', N'24 Hoàng Hoa Thám, Ba Đình, Hà Nội',   2,   NULL, 'thuthu02',  1, 0, 'PENDING');  -- da dong phi, DANG DOI CAP THE

-- Tai khoan READER (khong co ho so thanh vien, khong muon sach)
INSERT INTO users (username, password_hash, full_name, no_accent, email, role_id, is_active, failed_attempts, created_at)
SELECT v.username, @pwd, v.full_name, v.no_accent, v.email, r.id, 1, 0,
       DATEADD(DAY, -v.days_ago, SYSDATETIME())
FROM (VALUES
 ('reader',      N'Khách đọc demo',  'khach doc demo',  'reader@library.local',      30),
 ('khachtruong', N'Trương Văn Khách', 'truong van khach', 'khachtruong@example.com',   10)
) v(username, full_name, no_accent, email, days_ago)
JOIN roles r ON r.name = 'READER' AND r.is_deleted = 0;

-- Thu thu thu 2
INSERT INTO users (username, password_hash, full_name, no_accent, email, role_id, is_active, failed_attempts, created_at)
SELECT 'thuthu02', @pwd, N'Lê Thị Hạnh', 'le thi hanh', 'thuthu02@library.local', r.id, 1, 0,
       DATEADD(DAY, -365, SYSDATETIME())
FROM roles r WHERE r.name = 'LIBRARIAN' AND r.is_deleted = 0;

-- Tai khoan doc gia (tru 'user' da co tu V1)
INSERT INTO users (username, password_hash, full_name, no_accent, email, role_id, is_active, failed_attempts, created_at)
SELECT s.username, @pwd, s.full_name, s.no_accent, s.email, r.id, s.is_active, s.failed_attempts,
       DATEADD(MINUTE, 510, CAST(DATEADD(DAY, -s.reg_days_ago, @today) AS DATETIME2))
FROM #mem_seed s
JOIN roles r ON r.name = 'MEMBER' AND r.is_deleted = 0
WHERE s.username <> 'user';

-- ---------- AVATAR ----------
-- Gan xen ke 2 anh cho tat ca user (admin, thu thu, doc gia, reader)
UPDATE u SET u.avatar = CASE WHEN x.rn % 2 = 1 THEN @avatar1 ELSE @avatar2 END
FROM users u
JOIN (SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS rn
      FROM users WHERE is_deleted = 0) x ON x.id = u.id;

-- Ho so thanh vien (tru TV000001 da co tu V1)
-- card_expiry = ngay dang ky + 1 nam (+1 nam neu da gia han)
-- card_status = 'PENDING': da dong phi nhung chua duoc cap the (card_expiry chi la han du kien)
INSERT INTO members (user_id, member_code, phone, identity_number, address, card_expiry, card_status)
SELECT u.id, s.member_code, s.phone, s.identity_number, s.address,
       DATEADD(YEAR, CASE WHEN s.renew_days_before IS NULL THEN 1 ELSE 2 END,
               DATEADD(DAY, -s.reg_days_ago, @today)),
       s.card_status
FROM #mem_seed s
JOIN users u ON u.username = s.username AND u.is_deleted = 0
WHERE s.member_code <> 'TV000001';

-- Dong bo the cua TV000001 (V1 tao luc chay migration) voi ngay dang ky gia lap
UPDATE m SET m.card_expiry = DATEADD(YEAR, 1, DATEADD(DAY, -s.reg_days_ago, @today))
FROM members m JOIN #mem_seed s ON s.member_code = m.member_code
WHERE m.member_code = 'TV000001' AND m.is_deleted = 0;

-- ---------- MEMBER_PAYMENTS ----------
-- Phi dang ky (so tien lay tu settings.MEMBERSHIP_FEE)
INSERT INTO member_payments (member_id, amount, payment_type, paid_at, received_by, note)
SELECT m.id, CAST(st.setting_value AS DECIMAL(10,2)), 'REGISTER',
       DATEADD(MINUTE, 540 + CAST(m.id % 60 AS INT), CAST(DATEADD(DAY, -s.reg_days_ago, @today) AS DATETIME2)),
       rc.id, N'Đăng ký thẻ thành viên'
FROM #mem_seed s
JOIN members  m  ON m.member_code = s.member_code AND m.is_deleted = 0
JOIN users    rc ON rc.username   = s.registrar   AND rc.is_deleted = 0
JOIN settings st ON st.setting_key = 'MEMBERSHIP_FEE' AND st.is_deleted = 0;

-- Tai khoan doc gia duoc tao CUNG LUC voi viec nop phi dang ky
UPDATE u SET u.created_at = mp.paid_at
FROM users u
JOIN members m          ON m.user_id   = u.id AND m.is_deleted = 0
JOIN member_payments mp ON mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0
WHERE u.is_deleted = 0;

-- Ho so thanh vien cung duoc tao dung luc nop phi dang ky (truoc day members.created_at = ngay chay script)
UPDATE m SET m.created_at = mp.paid_at
FROM members m
JOIN member_payments mp ON mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0
WHERE m.is_deleted = 0;

-- Phi gia han (nop truoc ngay het han cu)
INSERT INTO member_payments (member_id, amount, payment_type, paid_at, received_by, note)
SELECT m.id, CAST(st.setting_value AS DECIMAL(10,2)), 'RENEW',
       DATEADD(MINUTE, 600,
         CAST(DATEADD(DAY, -s.renew_days_before,
                DATEADD(YEAR, 1, DATEADD(DAY, -s.reg_days_ago, @today))) AS DATETIME2)),
       rc.id, N'Gia hạn thẻ thành viên thêm 1 năm'
FROM #mem_seed s
JOIN members  m  ON m.member_code = s.member_code AND m.is_deleted = 0
JOIN users    rc ON rc.username   = 'thuthu02'   AND rc.is_deleted = 0
JOIN settings st ON st.setting_key = 'MEMBERSHIP_FEE' AND st.is_deleted = 0
WHERE s.renew_days_before IS NOT NULL;

-- Phi cap lai the (mat the / hong the) - chi voi thanh vien DA duoc cap the
-- Phi cap lai the = phi lam the cung (settings.CARD_MAKER_FEE)
INSERT INTO member_payments (member_id, amount, payment_type, paid_at, received_by, note)
SELECT m.id, CAST(st.setting_value AS DECIMAL(10,2)), 'REISSUE',
       DATEADD(MINUTE, v.minute_of_day, CAST(DATEADD(DAY, -v.days_ago, @today) AS DATETIME2)),
       rc.id, v.note
FROM (VALUES
 ('TV000006', 20, 'thuthu02',  570, N'Cấp lại thẻ do làm mất thẻ'),
 ('TV000010', 70, 'librarian', 620, N'Cấp lại thẻ do thẻ bị hỏng')
) v(member_code, days_ago, receiver, minute_of_day, note)
JOIN members m  ON m.member_code = v.member_code AND m.is_deleted = 0
JOIN users   rc ON rc.username   = v.receiver    AND rc.is_deleted = 0
JOIN settings st ON st.setting_key = 'CARD_MAKER_FEE' AND st.is_deleted = 0;

-- ---------- REFRESH_TOKENS ----------
INSERT INTO refresh_tokens (user_id, token, expires_at, revoked)
SELECT u.id,
       CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', CONCAT('seed-refresh-', v.username, '-', v.seq)), 2),
       DATEADD(DAY, v.expire_in_days, SYSDATETIME()),
       v.revoked
FROM (VALUES
 ('admin',        1,  7, 0),
 ('librarian',    1,  6, 0),
 ('thuthu02',     1,  5, 0),
 ('user',         1,  7, 0),
 ('user',         2, -3, 1),   -- da dang xuat (revoked)
 ('nguyenvanan',  1,  4, 0),
 ('tranthibinh',  1, -1, 0),   -- da het han
 ('lehoangcuong', 1,  3, 0),
 ('maithisen',    1, -10, 1),  -- tai khoan bi khoa, token bi thu hoi
 ('reader',       1,  2, 0)
) v(username, seq, expire_in_days, revoked)
JOIN users u ON u.username = v.username AND u.is_deleted = 0;

