-- ---------- COVER ----------
-- So thu tu sach chan -> @cover1 (BK-0002 "Toi thay hoa vang tren co xanh" khop dung anh bia),
-- so le -> @cover2
UPDATE books
SET cover = CASE WHEN CAST(RIGHT(book_code, 4) AS INT) % 2 = 0 THEN @cover1 ELSE @cover2 END
WHERE is_deleted = 0;

