-- =====================================================================
-- 3. MUON / TRA
-- =====================================================================
-- Phieu muon: BR01..BR18 = lich su (da tra het), BR20..BR29 = con sach chua tra.
-- Phieu KHONG co status; trang thai nam o tung cuon (borrow_details.status):
--   RETURNED  : da co return_date (ke ca tra tre)
--   OVERDUE   : chua tra va due_date < hom nay
--   BORROWING : chua tra va con han
-- (member, borrow_date) la duy nhat -> dung de map lai id phieu sau khi insert.
CREATE TABLE #br (
    ref              VARCHAR(10) PRIMARY KEY,
    member_code      VARCHAR(20),
    librarian        VARCHAR(50),
    borrow_days_ago  INT,
    loan_days        INT,
    note             NVARCHAR(255) NULL,
    id               BIGINT NULL
);

