INSERT INTO borrow_records (member_id, librarian_id, borrow_date, due_date, note)
SELECT m.id, l.id,
       DATEADD(DAY, -t.borrow_days_ago, @today),
       DATEADD(DAY, t.loan_days - t.borrow_days_ago, @today),
       t.note
FROM #br t
JOIN members m ON m.member_code = t.member_code AND m.is_deleted = 0
JOIN users   l ON l.username    = t.librarian   AND l.is_deleted = 0
ORDER BY t.ref;

UPDATE t SET t.id = br.id
FROM #br t
JOIN members        m  ON m.member_code = t.member_code
JOIN borrow_records br ON br.member_id = m.id
                      AND br.borrow_date = DATEADD(DAY, -t.borrow_days_ago, @today)
                      AND br.is_deleted = 0;

