-- status tinh theo TUNG cuon: da tra -> RETURNED; chua tra + qua han -> OVERDUE; con lai BORROWING
INSERT INTO borrow_details (borrow_id, book_id, return_date, status, fine_amount)
SELECT t.id, b.id,
       CASE WHEN d.return_days_ago IS NULL THEN NULL
            ELSE DATEADD(DAY, -d.return_days_ago, @today) END,
       CASE WHEN d.return_days_ago IS NOT NULL   THEN 'RETURNED'
            WHEN t.loan_days < t.borrow_days_ago THEN 'OVERDUE'      -- due_date < hom nay
            ELSE 'BORROWING' END,
       0
FROM #bd d
JOIN #br   t ON t.ref = d.ref
JOIN books b ON b.book_code = d.book_code AND b.is_deleted = 0
ORDER BY d.ref, d.book_code;

-- =====================================================================
-- 4. TIEN PHAT
-- =====================================================================
-- amount duoc TINH tu settings:
--   OVERDUE = overdue_days * FINE_OVERDUE_PER_DAY
--   LOST / DAMAGED_* = gia sach * he so (rate_key). rate_key PHAI khop voi reason:
--     DAMAGED_LIGHT -> FINE_DAMAGED_LIGHT_RATE, DAMAGED_HEAVY_REPAIRABLE -> FINE_DAMAGED_HEAVY_REPAIRABLE_RATE,
--     DAMAGED_HEAVY_IRREPARABLE -> FINE_DAMAGED_HEAVY_IRREPARABLE_RATE, LOST -> FINE_LOST_RATE
CREATE TABLE #fn (
    ref           VARCHAR(10),
    book_code     VARCHAR(30)  NULL,    -- NULL = phat chung ca phieu
    reason        VARCHAR(50),
    overdue_days  INT          NULL,
    rate_key      VARCHAR(100) NULL,
    ret_days_ago  INT,                  -- ngay lap phat (= ngay tra / bao mat)
    note          NVARCHAR(255),
    attach        BIT
);

