 ('BR17', 'BK-0008', 'DAMAGED_HEAVY_REPAIRABLE',  NULL,'FINE_DAMAGED_HEAVY_REPAIRABLE_RATE',  27, N'Sách hư nặng (bung gáy), có thể đóng lại', 1),
 ('BR18', 'BK-0014', 'DAMAGED_HEAVY_IRREPARABLE',  NULL,'FINE_DAMAGED_HEAVY_IRREPARABLE_RATE', 138, N'Sách hư nặng (ngấm nước, mục gáy), không thể phục hồi', 1);

INSERT INTO fines (borrow_id, borrow_detail_id, amount, reason, overdue_days, note, created_at, attachment)
SELECT t.id, bd.id,
       CASE f.reason
            WHEN 'OVERDUE' THEN CAST(f.overdue_days * CAST(sp.setting_value AS DECIMAL(10,2)) AS DECIMAL(10,2))
            ELSE CAST(bk.price * CAST(sr.setting_value AS DECIMAL(10,2)) AS DECIMAL(10,2))
       END,
       f.reason, f.overdue_days, f.note,
       DATEADD(HOUR, 10, CAST(DATEADD(DAY, -f.ret_days_ago, @today) AS DATETIME2)),
       CASE WHEN f.attach = 1 THEN @img ELSE NULL END
FROM #fn f
JOIN #br t ON t.ref = f.ref
JOIN settings sp ON sp.setting_key = 'FINE_OVERDUE_PER_DAY' AND sp.is_deleted = 0
LEFT JOIN settings sr ON sr.setting_key = f.rate_key AND sr.is_deleted = 0
LEFT JOIN books bk ON bk.book_code = f.book_code AND bk.is_deleted = 0
LEFT JOIN borrow_details bd ON bd.borrow_id = t.id AND bd.book_id = bk.id AND bd.is_deleted = 0;

-- fine_amount tren tung cuon = tong phat cua chinh cuon do
UPDATE bd SET bd.fine_amount = x.total
FROM borrow_details bd
JOIN (SELECT borrow_detail_id, SUM(amount) AS total
      FROM fines
      WHERE is_deleted = 0 AND borrow_detail_id IS NOT NULL
      GROUP BY borrow_detail_id) x ON x.borrow_detail_id = bd.id;

-- ---------- FINE_PAYMENTS ----------
-- Moi khoan nop deu SAU ngay phat sinh khoan phat va tong nop <= tong phat cua thanh vien.
INSERT INTO fine_payments (member_id, amount, paid_at, received_by, note)
SELECT m.id, v.amount,
       DATEADD(MINUTE, v.minute_of_day, CAST(DATEADD(DAY, -v.days_ago, @today) AS DATETIME2)),
       u.id, v.note
FROM (VALUES
 ('TV000002', 37500, 136, 'librarian', 600, N'Nộp phạt sách hư hỏng nặng, tất toán'),
 ('TV000003',  5000, 59, 'librarian', 600, N'Nộp phạt trả trễ'),
 ('TV000004', 30000, 49, 'librarian', 615, N'Nộp phạt trả trễ'),
 ('TV000004', 68000, 21, 'thuthu02',  630, N'Nộp phạt sách hư nặng'),   -- nop truoc ngay muon BR22 (T-20)
 ('TV000005', 15000, 74, 'thuthu02',  545, N'Nộp phạt đợt 1'),
 ('TV000005', 15000, 60, 'thuthu02',  550, N'Nộp phạt đợt 2, tất toán'),
 ('TV000009', 40000,  3, 'thuthu02',  580, N'Nộp một phần tiền phạt'),
 ('TV000010', 30000, 80, 'librarian', 560, N'Nộp một phần tiền phạt'),
 ('TV000011',  5000, 85, 'thuthu02',  660, N'Nộp phạt trả trễ'),
 ('TV000013', 80000, 95, 'librarian', 590, N'Nộp phạt trả trễ, tất toán')
) v(member_code, amount, days_ago, receiver, minute_of_day, note)
JOIN members m ON m.member_code = v.member_code AND m.is_deleted = 0
JOIN users   u ON u.username    = v.receiver    AND u.is_deleted = 0;

-- =====================================================================
-- 5. TON KHO: tinh lai tu du lieu muon/tra
--    quantity  : tru so cuon bi MAT (LOST) hoac HU NANG KHONG THE PHUC HOI (DAMAGED_HEAVY_IRREPARABLE)
--    available : quantity - so cuon dang duoc muon (status BORROWING / OVERDUE)
-- =====================================================================
UPDATE b SET
    b.quantity  = b.quantity - COALESCE(l.cnt, 0),
    b.available = b.quantity - COALESCE(l.cnt, 0) - COALESCE(o.cnt, 0)
FROM books b
LEFT JOIN (SELECT bd.book_id, COUNT(*) AS cnt
           FROM fines f
           JOIN borrow_details bd ON bd.id = f.borrow_detail_id AND bd.is_deleted = 0
           WHERE f.reason IN ('LOST', 'DAMAGED_HEAVY_IRREPARABLE') AND f.is_deleted = 0
           GROUP BY bd.book_id) l ON l.book_id = b.id
LEFT JOIN (SELECT bd.book_id, COUNT(*) AS cnt
           FROM borrow_details bd
           JOIN borrow_records br ON br.id = bd.borrow_id AND br.is_deleted = 0
           WHERE bd.status IN ('BORROWING','OVERDUE') AND bd.is_deleted = 0
           GROUP BY bd.book_id) o ON o.book_id = b.id
WHERE b.is_deleted = 0;

-- =====================================================================
-- 6. NOTIFICATIONS  (sinh tu du lieu that, khong go tay)
-- =====================================================================

-- 6.1 Dong phi dang ky / gia han the
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Bạn đã thanh toán ', FORMAT(mp.amount, 'N0', 'vi-VN'), N' VNĐ phí ',
              CASE mp.payment_type WHEN 'REGISTER' THEN N'đăng ký' WHEN 'RENEW' THEN N'gia hạn' ELSE N'cấp lại' END,
              N' thẻ thành viên.'),
       CASE WHEN mp.paid_at < DATEADD(DAY, -7, SYSDATETIME()) THEN 1 ELSE 0 END,
       mp.paid_at
FROM member_payments mp
JOIN members m ON m.id = mp.member_id
WHERE mp.is_deleted = 0;

-- 6.2 Bi phat
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Bạn bị phạt ', FORMAT(f.amount, 'N0', 'vi-VN'), N' VNĐ ',
              CASE f.reason
                   WHEN 'OVERDUE' THEN CONCAT(N'do trả sách trễ ', f.overdue_days, N' ngày')
                   WHEN 'LOST'    THEN N'do làm mất sách'
                   ELSE N'do làm hư hỏng sách'
              END,
              CASE WHEN bk.title IS NOT NULL THEN CONCAT(N' (', bk.title, N')') ELSE N'' END,
              N'.'),
       CASE WHEN f.created_at < DATEADD(DAY, -7, SYSDATETIME()) THEN 1 ELSE 0 END,
       f.created_at
FROM fines f
JOIN borrow_records br ON br.id = f.borrow_id
JOIN members m ON m.id = br.member_id
LEFT JOIN borrow_details bd ON bd.id = f.borrow_detail_id
LEFT JOIN books bk ON bk.id = bd.book_id
WHERE f.is_deleted = 0;

-- 6.3 Da nop tien phat
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Thư viện đã ghi nhận bạn nộp ', FORMAT(fp.amount, 'N0', 'vi-VN'), N' VNĐ tiền phạt.'),
       CASE WHEN fp.paid_at < DATEADD(DAY, -7, SYSDATETIME()) THEN 1 ELSE 0 END,
       fp.paid_at
FROM fine_payments fp
JOIN members m ON m.id = fp.member_id
WHERE fp.is_deleted = 0;

-- 6.4 Nhac han tra: gui truoc han DUE_REMINDER_DAYS ngay (settings), cho moi cuon CHUA TRA
--     (BORROWING hoac OVERDUE) ma moc nhac da toi. Thoi diem tao = 08:00 cua ngay nhac.
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Sách "', bk.title, N'" sẽ đến hạn trả vào ngày ',
              CONVERT(NVARCHAR(10), br.due_date, 103), N'. Vui lòng trả sách đúng hạn.'),
       CASE WHEN rm.remind_at < DATEADD(DAY, -7, SYSDATETIME()) THEN 1 ELSE 0 END,
       rm.remind_at
FROM borrow_records br
JOIN members m ON m.id = br.member_id
JOIN borrow_details bd ON bd.borrow_id = br.id AND bd.is_deleted = 0 AND bd.status IN ('BORROWING','OVERDUE')
JOIN books bk ON bk.id = bd.book_id
CROSS APPLY (SELECT DATEADD(HOUR, 8, CAST(DATEADD(DAY, -@remind_days, br.due_date) AS DATETIME2)) AS remind_at) rm
WHERE br.is_deleted = 0
  AND rm.remind_at <= SYSDATETIME();

-- 6.5 Qua han (tam tinh tien phat theo settings) - theo tung cuon OVERDUE
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Sách "', bk.title, N'" đã quá hạn ', DATEDIFF(DAY, br.due_date, @today),
              N' ngày (hạn trả ', CONVERT(NVARCHAR(10), br.due_date, 103),
              N'). Tiền phạt tạm tính: ',
              FORMAT(DATEDIFF(DAY, br.due_date, @today) * CAST(sp.setting_value AS DECIMAL(10,2)), 'N0', 'vi-VN'),
              N' VNĐ.'),
       0,
       @morning
FROM borrow_records br
JOIN members m ON m.id = br.member_id
JOIN borrow_details bd ON bd.borrow_id = br.id AND bd.is_deleted = 0 AND bd.status = 'OVERDUE'
JOIN books bk ON bk.id = bd.book_id
JOIN settings sp ON sp.setting_key = 'FINE_OVERDUE_PER_DAY' AND sp.is_deleted = 0
WHERE br.is_deleted = 0;

-- 6.6 The thanh vien het han
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Thẻ thành viên của bạn đã hết hạn từ ngày ', CONVERT(NVARCHAR(10), m.card_expiry, 103),
              N'. Vui lòng gia hạn để tiếp tục mượn sách.'),
       0,
       DATEADD(HOUR, 8, CAST(m.card_expiry AS DATETIME2))
FROM members m
WHERE m.is_deleted = 0 AND m.card_status = 'ISSUED' AND m.card_expiry < @today;

-- 6.6b The dang doi cap
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       N'Bạn đã đóng phí đăng ký thẻ thành viên. Thẻ đang chờ thư viện cấp, vui lòng đến quầy thủ thư để nhận thẻ trước khi mượn sách.',
       0,
       DATEADD(MINUTE, 5, mp.paid_at)
FROM members m
JOIN member_payments mp ON mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0
WHERE m.is_deleted = 0 AND m.card_status = 'PENDING';

-- 6.7 No phat vuot nguong -> bi chan muon them
INSERT INTO notifications (user_id, content, is_read, created_at)
SELECT m.user_id,
       CONCAT(N'Tổng tiền phạt còn nợ của bạn là ', FORMAT(d.debt, 'N0', 'vi-VN'),
              N' VNĐ, vượt mức cho phép ', FORMAT(CAST(s.setting_value AS DECIMAL(10,2)), 'N0', 'vi-VN'),
              N' VNĐ. Bạn không thể mượn thêm sách cho đến khi thanh toán phần còn nợ.'),
       0,
       @morning
FROM members m
CROSS APPLY (
    SELECT COALESCE((SELECT SUM(f.amount)
                     FROM fines f JOIN borrow_records br ON br.id = f.borrow_id
                     WHERE br.member_id = m.id AND f.is_deleted = 0), 0)
         - COALESCE((SELECT SUM(fp.amount)
                     FROM fine_payments fp
                     WHERE fp.member_id = m.id AND fp.is_deleted = 0), 0) AS debt
) d
JOIN settings s ON s.setting_key = 'MAX_FINE_BEFORE_BLOCK' AND s.is_deleted = 0
WHERE m.is_deleted = 0
  AND d.debt > CAST(s.setting_value AS DECIMAL(10,2));

-- =====================================================================
-- 7. KIEM TRA TINH NHAT QUAN (loi => THROW => rollback toan bo)
-- =====================================================================

-- 7.1 Tong tien da nop phat khong vuot tong tien bi phat cua thanh vien
IF EXISTS (
    SELECT 1
    FROM members m
    WHERE COALESCE((SELECT SUM(fp.amount) FROM fine_payments fp
                    WHERE fp.member_id = m.id AND fp.is_deleted = 0), 0)
        > COALESCE((SELECT SUM(f.amount) FROM fines f
                    JOIN borrow_records br ON br.id = f.borrow_id
                    WHERE br.member_id = m.id AND f.is_deleted = 0), 0)
)
    THROW 50001, N'Seed loi: tong tien nop phat > tong tien bi phat.', 1;

-- 7.2 Ngay tra phai >= ngay muon
IF EXISTS (
    SELECT 1 FROM borrow_details bd
    JOIN borrow_records br ON br.id = bd.borrow_id
    WHERE bd.is_deleted = 0 AND br.is_deleted = 0
      AND bd.return_date IS NOT NULL AND bd.return_date < br.borrow_date
)
    THROW 50002, N'Seed loi: co cuon sach tra truoc ngay muon.', 1;

-- 7.3 Trang thai TUNG cuon khop voi return_date + han tra cua phieu
IF EXISTS (
    SELECT 1 FROM borrow_details bd
    JOIN borrow_records br ON br.id = bd.borrow_id
    WHERE bd.is_deleted = 0 AND br.is_deleted = 0 AND (
          (bd.status = 'RETURNED'  AND bd.return_date IS NULL)
       OR (bd.status = 'BORROWING' AND (bd.return_date IS NOT NULL OR br.due_date < @today))
       OR (bd.status = 'OVERDUE'   AND (bd.return_date IS NOT NULL OR br.due_date >= @today)))
)
    THROW 50003, N'Seed loi: status cua borrow_details khong khop return_date / han tra.', 1;

-- 7.4 So ngay tre trong fines khop voi (ngay tra - han tra) cua cuon sach
IF EXISTS (
    SELECT 1 FROM fines f
    JOIN borrow_details bd ON bd.id = f.borrow_detail_id
    JOIN borrow_records br ON br.id = bd.borrow_id
    WHERE f.reason = 'OVERDUE' AND f.is_deleted = 0
      AND bd.is_deleted = 0 AND br.is_deleted = 0
      AND (bd.return_date IS NULL
           OR f.overdue_days IS NULL
           OR f.overdue_days <> DATEDIFF(DAY, br.due_date, bd.return_date))
)
    THROW 50004, N'Seed loi: overdue_days khong khop ngay tra thuc te.', 1;

-- 7.5 Moi phieu muon xay ra khi the DA CAP, con han va sau ngay dang ky the
IF EXISTS (
    SELECT 1 FROM borrow_records br
    JOIN members m ON m.id = br.member_id
    WHERE m.card_status <> 'ISSUED'
       OR br.borrow_date > m.card_expiry
       OR br.borrow_date < (SELECT CAST(MIN(mp.paid_at) AS DATE) FROM member_payments mp
                            WHERE mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0)
)
    THROW 50005, N'Seed loi: phieu muon cua the chua cap / ngoai thoi han the thanh vien.', 1;

-- 7.6 So sach dang muon (BORROWING / OVERDUE) cua moi thanh vien khong vuot MAX_BOOKS_BORROW
IF EXISTS (
    SELECT 1 FROM borrow_records br
    JOIN borrow_details bd ON bd.borrow_id = br.id AND bd.is_deleted = 0 AND bd.status IN ('BORROWING','OVERDUE')
    JOIN settings s ON s.setting_key = 'MAX_BOOKS_BORROW' AND s.is_deleted = 0
    WHERE br.is_deleted = 0
    GROUP BY br.member_id, s.setting_value
    HAVING COUNT(*) > CAST(s.setting_value AS INT)
)
    THROW 50006, N'Seed loi: thanh vien dang muon vuot so sach toi da.', 1;

-- 7.7 Thoi gian muon moi phieu khong vuot MAX_BORROW_DAYS
IF EXISTS (
    SELECT 1 FROM borrow_records br
    JOIN settings s ON s.setting_key = 'MAX_BORROW_DAYS' AND s.is_deleted = 0
    WHERE DATEDIFF(DAY, br.borrow_date, br.due_date) > CAST(s.setting_value AS INT)
)
    THROW 50007, N'Seed loi: phieu muon vuot so ngay muon toi da.', 1;

-- 7.8 fine_amount tung cuon = tong fines cua cuon do
IF EXISTS (
    SELECT 1 FROM borrow_details bd
    WHERE bd.is_deleted = 0
      AND COALESCE(bd.fine_amount, 0) <> COALESCE((SELECT SUM(f.amount) FROM fines f
                                                   WHERE f.borrow_detail_id = bd.id AND f.is_deleted = 0), 0)
)
    THROW 50008, N'Seed loi: borrow_details.fine_amount khong khop bang fines.', 1;

-- 7.9 Moi user role MEMBER phai co dung 1 ban ghi members (khong co thi chi la khach, khong co tai khoan)
IF EXISTS (
    SELECT 1 FROM users u
    JOIN roles r ON r.id = u.role_id AND r.name = 'MEMBER' AND r.is_deleted = 0
    WHERE u.is_deleted = 0
      AND (SELECT COUNT(*) FROM members m WHERE m.user_id = u.id AND m.is_deleted = 0) <> 1
)
    THROW 50009, N'Seed loi: co user MEMBER khong co (hoac co nhieu) ban ghi members.', 1;

-- 7.10 Moi member phai thuoc ve user role MEMBER (nhan su khong phai thanh vien)
IF EXISTS (
    SELECT 1 FROM members m
    JOIN users u ON u.id = m.user_id
    JOIN roles r ON r.id = u.role_id
    WHERE m.is_deleted = 0 AND r.name <> 'MEMBER'
)
    THROW 50010, N'Seed loi: co member gan voi user khong phai role MEMBER.', 1;

-- 7.11 Moi member co dung 1 khoan phi dang ky, user duoc tao dung luc nop phi,
--      va nguoi thu phi la thu thu da ton tai tu truoc do
IF EXISTS (
    SELECT 1 FROM members m
    JOIN users u ON u.id = m.user_id
    WHERE m.is_deleted = 0
      AND ( (SELECT COUNT(*) FROM member_payments mp
             WHERE mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0) <> 1
         OR NOT EXISTS (SELECT 1 FROM member_payments mp
                        JOIN users rc ON rc.id = mp.received_by
                        WHERE mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0
                          AND mp.paid_at = u.created_at AND rc.created_at <= mp.paid_at) )
)
    THROW 50011, N'Seed loi: phi dang ky / ngay tao tai khoan / thu thu thu phi khong khop.', 1;

-- 7.12 Phi gia han / cap lai chi co o thanh vien da tung dang ky, nop sau ngay dang ky
IF EXISTS (
    SELECT 1 FROM member_payments rn
    JOIN member_payments rg ON rg.member_id = rn.member_id AND rg.payment_type = 'REGISTER' AND rg.is_deleted = 0
    WHERE rn.payment_type IN ('RENEW','REISSUE') AND rn.is_deleted = 0 AND rn.paid_at <= rg.paid_at
)
    THROW 50012, N'Seed loi: phi gia han / cap lai nop truoc ngay dang ky.', 1;

-- 7.12b Cap lai the chi danh cho thanh vien da duoc cap the (ISSUED)
IF EXISTS (
    SELECT 1 FROM member_payments mp
    JOIN members m ON m.id = mp.member_id
    WHERE mp.payment_type = 'REISSUE' AND mp.is_deleted = 0 AND m.card_status <> 'ISSUED'
)
    THROW 50014, N'Seed loi: REISSUE cho thanh vien chua duoc cap the.', 1;

-- 7.13 READER phai co DUNG 10 quyen (khop V1__init_schema.sql ban moi: them ROLE_READ,
--      CATEGORY_READ, AUTHOR_READ, PUBLISHER_READ, SHELF_READ so voi ban cu 5 quyen)
DECLARE @reader_perm_cnt INT = (
    SELECT COUNT(*) FROM role_permissions rp
    JOIN roles r       ON r.id = rp.role_id AND r.name = 'READER' AND r.is_deleted = 0
    JOIN permissions p ON p.id = rp.permission_id AND p.is_deleted = 0
    WHERE p.code IN ('USER_READ','USER_WRITE','ROLE_READ',
                     'BOOK_READ','CATEGORY_READ','AUTHOR_READ','PUBLISHER_READ','SHELF_READ',
                     'NOTIFICATION_READ','NOTIFICATION_WRITE'));
DECLARE @reader_perm_all INT = (
    SELECT COUNT(*) FROM role_permissions rp
    JOIN roles r ON r.id = rp.role_id AND r.name = 'READER' AND r.is_deleted = 0);
IF @reader_perm_cnt <> 10 OR @reader_perm_all <> 10
    THROW 50013, N'Seed loi: role READER phai co dung 10 quyen (USER_READ, USER_WRITE, ROLE_READ, BOOK_READ, CATEGORY_READ, AUTHOR_READ, PUBLISHER_READ, SHELF_READ, NOTIFICATION_READ, NOTIFICATION_WRITE).', 1;

-- 7.14 members.created_at = thoi diem nop phi dang ky
IF EXISTS (
    SELECT 1 FROM members m
    JOIN member_payments mp ON mp.member_id = m.id AND mp.payment_type = 'REGISTER' AND mp.is_deleted = 0
    WHERE m.is_deleted = 0
      AND (m.created_at IS NULL OR m.created_at <> mp.paid_at)
)
    THROW 50016, N'Seed loi: members.created_at khong khop thoi diem nop phi dang ky.', 1;

-- 7.15 Tien phat LOST / DAMAGED_* = gia sach * dung he so cua reason; OVERDUE = so ngay tre * muc phat / ngay
IF EXISTS (
    SELECT 1 FROM fines f
    JOIN borrow_details bd ON bd.id = f.borrow_detail_id
    JOIN books b ON b.id = bd.book_id
    LEFT JOIN settings s ON s.is_deleted = 0 AND s.setting_key = CASE f.reason
         WHEN 'LOST'                      THEN 'FINE_LOST_RATE'
         WHEN 'DAMAGED_LIGHT'             THEN 'FINE_DAMAGED_LIGHT_RATE'
         WHEN 'DAMAGED_HEAVY_REPAIRABLE'  THEN 'FINE_DAMAGED_HEAVY_REPAIRABLE_RATE'
         WHEN 'DAMAGED_HEAVY_IRREPARABLE' THEN 'FINE_DAMAGED_HEAVY_IRREPARABLE_RATE' END
    WHERE f.is_deleted = 0 AND f.reason <> 'OVERDUE'
      AND (s.id IS NULL OR f.amount <> b.price * CAST(s.setting_value AS DECIMAL(10,2)))
)
    THROW 50017, N'Seed loi: so tien phat LOST/DAMAGED khong khop gia sach * he so cua reason.', 1;

IF EXISTS (
    SELECT 1 FROM fines f
    JOIN settings s ON s.setting_key = 'FINE_OVERDUE_PER_DAY' AND s.is_deleted = 0
    WHERE f.is_deleted = 0 AND f.reason = 'OVERDUE'
      AND f.amount <> f.overdue_days * CAST(s.setting_value AS DECIMAL(10,2))
)
    THROW 50018, N'Seed loi: tien phat OVERDUE khong khop so ngay tre * muc phat.', 1;

-- 7.16 Khong cho muon khi no phat (tinh den thoi diem muon) vuot MAX_FINE_BEFORE_BLOCK
--      (khoan phat tinh neu phat sinh trong/truoc ngay muon; khoan nop chi tinh neu nop TRUOC ngay muon)
IF EXISTS (
    SELECT 1 FROM borrow_records br
    JOIN settings s ON s.setting_key = 'MAX_FINE_BEFORE_BLOCK' AND s.is_deleted = 0
    WHERE br.is_deleted = 0
      AND COALESCE((SELECT SUM(f.amount) FROM fines f
                    JOIN borrow_records b2 ON b2.id = f.borrow_id
                    WHERE b2.member_id = br.member_id AND f.is_deleted = 0
                      AND CAST(f.created_at AS DATE) <= br.borrow_date), 0)
        - COALESCE((SELECT SUM(fp.amount) FROM fine_payments fp
                    WHERE fp.member_id = br.member_id AND fp.is_deleted = 0
                      AND CAST(fp.paid_at AS DATE) < br.borrow_date), 0)
        > CAST(s.setting_value AS DECIMAL(10,2))
)
    THROW 50019, N'Seed loi: co phieu muon duoc lap khi thanh vien dang no phat vuot nguong.', 1;

-- 7.17 avatar / cover phai la data URI (giong quy uoc V1)
IF EXISTS (SELECT 1 FROM users WHERE is_deleted = 0 AND (avatar IS NULL OR avatar NOT LIKE 'data:image/%;base64,%'))
   OR EXISTS (SELECT 1 FROM books WHERE is_deleted = 0 AND (cover IS NULL OR cover NOT LIKE 'data:image/%;base64,%'))
    THROW 50020, N'Seed loi: avatar / cover khong phai data URI base64.', 1;

DROP TABLE #fn;
DROP TABLE #bd;
DROP TABLE #br;
DROP TABLE #mem_seed;

COMMIT TRANSACTION;